// Step 1 (rest of it) — normalize whatever shape RealtyAPI returned into a
// flat list of property items, mirroring shadescout/clients/realty.py
// _extract_records / _to_listings_realtyapi. Field names are unverified
// against a live RealtyAPI response (their docs site blocks automated
// fetching) — if this produces zero properties, log $json here and adjust
// ADDRESS_KEYS / SALE_DATE_KEYS / PRICE_KEYS / CONTAINER_KEYS below.

const ADDRESS_KEYS = ['formattedAddress', 'full_address', 'fullAddress', 'address', 'streetAddress', 'location'];
const SALE_DATE_KEYS = ['lastSaleDate', 'soldDate', 'sold_date', 'closeDate', 'close_date', 'dateSold'];
const PRICE_KEYS = ['lastSalePrice', 'soldPrice', 'sold_price', 'price', 'closePrice'];
const CONTAINER_KEYS = ['results', 'properties', 'listings', 'data', 'homes'];

function first(record, keys) {
  for (const key of keys) {
    if (record[key] !== undefined && record[key] !== null && record[key] !== '') return record[key];
  }
  return null;
}

function formatAddress(value) {
  if (typeof value === 'string') return value;
  if (value && typeof value === 'object') {
    const parts = ['line', 'street', 'streetAddress', 'city', 'state', 'zip', 'zipcode', 'postal_code']
      .map((k) => value[k])
      .filter(Boolean);
    return parts.length ? parts.join(', ') : null;
  }
  return null;
}

function daysSince(isoDate) {
  const parsed = new Date(isoDate);
  if (isNaN(parsed.getTime())) return null;
  return Math.floor((Date.now() - parsed.getTime()) / 86400000);
}

const body = $input.first().json;
let records = Array.isArray(body) ? body : null;
if (!records) {
  for (const key of CONTAINER_KEYS) {
    if (Array.isArray(body[key])) {
      records = body[key];
      break;
    }
  }
}
if (!records) {
  throw new Error('RealtyAPI response had no recognizable list of properties. Keys seen: ' + JSON.stringify(Object.keys(body || {})));
}

const config = $('Config').first().json;

const listings = [];
for (const record of records) {
  const address = formatAddress(first(record, ADDRESS_KEYS));
  if (!address) continue;
  const saleDate = first(record, SALE_DATE_KEYS);
  if (saleDate) {
    const age = daysSince(saleDate);
    if (age !== null && age > config.maxDaysSinceSale) continue;
  }
  listings.push({
    formattedAddress: address,
    lastSaleDate: saleDate,
    price: first(record, PRICE_KEYS),
  });
}

listings.sort((a, b) => (b.lastSaleDate || '').localeCompare(a.lastSaleDate || ''));

return listings.slice(0, config.limit).map((listing) => ({ json: listing }));

// Steps 4-7 for every property that made it through geocoding: fetch
// satellite + street view imagery, run the OpenRouter vision analysis with
// the exact required prompt, apply the has_patio/already_covered filter,
// and build the postcard copy. Mirrors shadescout/pipeline.py process_property
// + build_postcard_text. Runs once for ALL items (not per-item) so a
// failure on one property can be caught and skipped without dropping the
// whole batch — matching the Python pipeline's per-property error isolation.

const config = $('Config').first().json;
const properties = $('2. Normalize & Filter Properties').all();
const geocodes = $input.all(); // same order/length as `properties`, 1:1

const GOOGLE_KEY = $env.GOOGLE_MAPS_API_KEY;
const OPENROUTER_KEY = $env.OPENROUTER_API_KEY;

const PROMPT = `Image 1 below is a top-down satellite view (zoom 20) of the property. Image 2 is a street-level view of the same address for additional context.

You are an expert landscape and shade analyst. Look at this satellite image of a residential property.
1. Does this home have a backyard patio or deck? (Yes/No)
2. Is there already a solid roof, pergola, or heavy tree cover shading the patio? (Yes/No)
3. Based on the sun's trajectory (assume south-facing gets the most sun in the US), estimate how many hours of direct, punishing sunlight this patio gets per day.
4. Return ONLY a valid JSON object exactly like this: {"has_patio": true, "already_covered": false, "estimated_sun_hours": 10}`;

async function fetchImageBase64(url, qs) {
  const buffer = await this.helpers.httpRequest({ method: 'GET', url, qs, encoding: 'arraybuffer' });
  return Buffer.from(buffer).toString('base64');
}

async function fetchUpcomingHotDay(lat, lng) {
  try {
    const weather = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.open-meteo.com/v1/forecast',
      qs: {
        latitude: lat,
        longitude: lng,
        daily: 'temperature_2m_max',
        temperature_unit: 'fahrenheit',
        forecast_days: 7,
        timezone: 'auto',
      },
      json: true,
    });
    const highs = weather?.daily?.temperature_2m_max || [];
    const dates = weather?.daily?.time || [];
    if (!highs.length) return null;
    const idx = highs.indexOf(Math.max(...highs));
    const day = new Date(dates[idx]).toLocaleDateString('en-US', { weekday: 'long' });
    return { day, tempF: Math.round(highs[idx]) };
  } catch (err) {
    return null; // best-effort only, matches shadescout/clients/weather.py
  }
}

function buildPostcardText(sunHours, hotDay) {
  if (hotDay) {
    return `Your patio takes ${sunHours} hours of direct sun a day. This ${hotDay.day} it hits ${hotDay.tempF}°. Scan this QR code to see how a louvered pergola looks in your exact backyard.`;
  }
  return `Your patio takes ${sunHours} hours of direct, punishing sun a day. Scan this QR code to see how a louvered pergola looks in your exact backyard.`;
}

const qualifiedLeads = [];

for (let i = 0; i < geocodes.length; i++) {
  const geocode = geocodes[i].json;
  const property = properties[i].json;
  const address = property.formattedAddress;

  try {
    if (geocode.status !== 'OK' || !geocode.results || !geocode.results.length) {
      continue; // geocoding failed for this address, skip it
    }
    const { lat, lng } = geocode.results[0].geometry.location;

    const satelliteB64 = await fetchImageBase64.call(this, 'https://maps.googleapis.com/maps/api/staticmap', {
      center: `${lat},${lng}`,
      zoom: 20,
      maptype: 'satellite',
      size: '640x640',
      key: GOOGLE_KEY,
    });
    const streetB64 = await fetchImageBase64.call(this, 'https://maps.googleapis.com/maps/api/streetview', {
      location: `${lat},${lng}`,
      size: '640x640',
      key: GOOGLE_KEY,
    });

    const visionResp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://openrouter.ai/api/v1/chat/completions',
      headers: {
        Authorization: `Bearer ${OPENROUTER_KEY}`,
        'Content-Type': 'application/json',
      },
      body: {
        model: config.visionModel,
        messages: [
          {
            role: 'user',
            content: [
              { type: 'text', text: PROMPT },
              { type: 'image_url', image_url: { url: `data:image/png;base64,${satelliteB64}` } },
              { type: 'image_url', image_url: { url: `data:image/png;base64,${streetB64}` } },
            ],
          },
        ],
      },
      json: true,
    });

    const content = visionResp?.choices?.[0]?.message?.content;
    const match = content && content.match(/\{[\s\S]*\}/);
    if (!match) continue; // vision model gave no parseable JSON, skip

    const analysis = JSON.parse(match[0]);
    if (!analysis.has_patio || analysis.already_covered) continue; // disqualified

    const sunHours = Number(analysis.estimated_sun_hours);
    const hotDay = await fetchUpcomingHotDay.call(this, lat, lng);

    qualifiedLeads.push({
      json: {
        lead_status: 'QUALIFIED',
        property_address: address,
        coordinates: { lat, lng },
        sun_hours: sunHours,
        postcard_text: buildPostcardText(sunHours, hotDay),
      },
    });
  } catch (err) {
    // isolate failures per-property instead of aborting the whole run
    continue;
  }
}

return qualifiedLeads;
